#include "RotatingBounds.h"
#include <iostream>
#include <random>
#include <chrono>
int main(){using namespace m87_proposal;std::mt19937_64 rng(0x871234abcdefULL);std::uniform_real_distribution<float> unit(-1.f,1.f),dimension(.001f,3.f);size_t checked=0,fail=0,accept=0,reject=0;
for(unsigned i=0;i<2400;++i){RigidBody body;body.inverseMass=1;body.inverseInertiaLocal=glm::mat3(1);body.orientation=glm::normalize(glm::quat(unit(rng),unit(rng),unit(rng),unit(rng)));body.position=glm::vec3(unit(rng),unit(rng),unit(rng))*std::pow(10.f,float(i%9)*3);body.linearVelocity=glm::vec3(unit(rng),unit(rng),unit(rng))*std::pow(10.f,float(i%7)-2);body.angularVelocity=glm::vec3(unit(rng),unit(rng),unit(rng))*std::pow(10.f,float(i%8)-3);const double duration=.016;RigidMotion motion;motion.Begin(i+1,body,duration);const double start=duration*double(i%16)/17.;const auto from=motion.EvaluateAfterEvents(start),to=motion.EvaluateAfterEvents(duration);const auto shape=Shape::Box(glm::vec3(dimension(rng),dimension(rng),dimension(rng)));const auto bound=TryDynamicBoxSweepBound(shape,motion.Segments().back(),from,to,start,duration);if(!bound){++reject;continue;}++accept;for(unsigned sample=0;sample<=64;++sample){const double time=sample==64?duration:start+(duration-start)*double(sample)/64.;const auto pose=motion.EvaluateAfterEvents(time);const auto actual=ShapeAabb(shape,pose.position,pose.orientation);++checked;if(!bound->Contains(actual)){++fail;if(fail<8)std::cerr<<"miss i="<<i<<" sample="<<sample<<'\n';}}}
RigidBody body;body.inverseMass=1;body.inverseInertiaLocal=glm::mat3(1);body.angularVelocity={.01f,.3f,.9f};body.orientation=glm::normalize(glm::quat(.5f,.3f,.4f,.2f));RigidMotion motion;motion.Begin(1,body,.016);const auto shape=Shape::Box({.3f,.3f,.3f});const auto from=motion.EvaluateAfterEvents(0),to=motion.EvaluateAfterEvents(.016);const auto begin=std::chrono::steady_clock::now();float checksum=0;for(unsigned i=0;i<10000;++i){const auto b=TryDynamicBoxSweepBound(shape,motion.Segments().back(),from,to,0,.016);if(b)checksum+=b->max.x;}const auto us=std::chrono::duration<double,std::micro>(std::chrono::steady_clock::now()-begin).count()/10000.;std::cout<<"checks="<<checked<<" failures="<<fail<<" accepted="<<accept<<" fallback="<<reject<<" bound_us="<<us<<" checksum="<<checksum<<'\n';return fail?1:0;}
